#!/usr/bin/env python3
"""Render the honest per-method checkpoint from its inventory/line/exit snapshot."""
import json
import pathlib
import sys

snapshot = json.loads(pathlib.Path(sys.argv[1]).read_text())
lines = ['# Coverage checkpoint', '', f"Baseline: `{snapshot['baseline']}`; PHP {snapshot['runtime']}; Xdebug {snapshot['xdebug']}. This checkpoint is incomplete and production regressions remain red.", '', 'Clover supplies executable lines for loose PHP and byte-identical archive measurement copies. Raw Xdebug lines preserve physical PHAR-stub execution. Actual Xdebug `out` / `out_hit` counters supply opcode exits; block hits alone are not branch proof. Synthetic return exits and zero-iteration edges over fixed nonempty arrays remain uncovered. Native subprocess graphs and parent graphs remain separate; missing data stays unknown. Xdebug 3.1.6 misattributes the conditional Bridge/EE constructor graph to its first declaration; Reflection detects mismatched runtime ranges, which retain unknown per-method branch metrics. Separate native contexts are recorded in `NATIVE_COVERAGE.md`.', '', 'All 27 shipped source units remain inventoried, including the PHAR stub, procedural files, archive views, and abstract declarations. Measurement copies are verified by SHA-256 before loading. Source is never excluded to improve the result. The raw collector installs an early filter and filters persisted JSON to the entire loose source tree, physical PHAR, and all PHAR members. A source-graph guard rejects an empty source measurement; unobserved inventory units remain visible.', '', '| Source | Lines hit / executable | Parent procedural exits | Uncovered lines |', '|---|---:|---:|---|']
for source in snapshot['files']:
    coverage = 'unknown' if source['executable_lines'] is None else f"{source['covered_lines']}/{source['executable_lines']}"
    graphs = source['procedural_graphs']
    procedural = ', '.join(f"{graph['exits_hit']}/{graph['exits']}" for graph in graphs) or ('not applicable' if source['procedural_branch_metrics'].startswith('not applicable') else 'unknown')
    missing = 'unknown' if source['uncovered_lines'] is None else ', '.join(map(str, source['uncovered_lines'])) or 'none'
    lines.append(f"| `{source['file']}` | {coverage} | {procedural} | {missing} |")
lines += ['', 'Procedural units are identified in `source-inventory.json`; class-only units have declarations rather than executable procedural regions. Captured parent procedural graphs are retained above, including zero-hit graphs. Native extraction/loading paths execute separately and are not merged into those graphs.', '', '| Function / method | Lines hit / executable | Blocks hit / total | Exits hit / total | Uncovered exit line -> target |', '|---|---:|---:|---:|---|']
for source in snapshot['files']:
    for method in source['methods']:
        def fraction(hit, total):
            return 'unknown' if total is None else f'{hit}/{total}'
        missing = 'abstract declaration' if not method['executable'] else ', '.join(f"{exit['line']}->{exit['target']}" for exit in method['uncovered_exits'] or []) or ('unknown' if method['xdebug_exits'] is None else 'none')
        lines.append(f"| `{source['file']}::{method['name']}:{method['start_line']}` | {fraction(method['lines_hit'], method['lines'])} | {fraction(method['xdebug_blocks_hit'], method['xdebug_blocks'])} | {fraction(method['xdebug_exits_hit'], method['xdebug_exits'])} | {missing} |")
lines += ['', '## Remaining constraints', '', '- Archived `Conduit/McpNav.php` cannot load under strict diagnostics: line 7 includes an absent loose `Conduit/McpNav.php` under `@`. Its methods remain unexecuted; source is not invented or suppressed to bypass this.', '- `Base/Pi::info()` fails immediately by using `$this` statically. Its later lines require a source fix.', '- `Base/Upd::update()` reaches the absent optional `ext.low_title.php`; the required diagnostic blocks subsequent success/catch paths.', '- Cache creation emits an `@mkdir` warning before later logging/false-return lines when a file occupies a directory path. Both source regressions are retained.', '- Modern `ee(\'db\')` supplies a fresh builder with empty `data_cache`; no fake preloaded primary cache is reused to reach its cache-flush guard. Legacy settings use the actual clone contract. The missed modern guard remains visible.', '- CP-only constructors, alternate EE selection, archive index callbacks, and extraction have isolated native contexts where applicable; their graphs are not merged into parent coverage. Physical extraction-stub graphs are preserved: helper methods execute in the parent, while `go()` remains unexecuted there. Native integrity-error paths remain separate.', '- PHP < 5.3.6 and Windows branches cannot execute on the required macOS Herd matrix. The shipped `FluxCapacitor::L` constant is `false`, so its true paths require source changes.', '- EE2 inline views write only inside a disposable installation containing a hash-verified copy of the shipped PHAR. Production paths are never written.', '', 'The mandatory skill helper reports 7 loose methods and 201 archive methods. Its `at_target` labels treat missing Clover branch metrics as sufficient; those labels are line-progress information and never campaign-completion evidence.', '']
pathlib.Path(sys.argv[2]).write_text('\n'.join(lines))
